"""사용자 한 명과 그 사용자의 auto-generated file, 그 파일에 대한 권한."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass
from typing import Any, override

import sqlalchemy as sa

from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileEntityType
from ai.backend.common.data.entity.user import UserID
from ai.backend.manager.data.auto_generated_file.types import (
    AutoGeneratedFileData,
    AutoGeneratedFileRevisionData,
)
from ai.backend.manager.data.permission.types import Permission
from ai.backend.manager.data.user.types import UserData
from ai.backend.manager.models.auto_generated_file.row import AutoGeneratedFileRow
from ai.backend.manager.models.auto_generated_file_revision.row import AutoGeneratedFileRevisionRow
from ai.backend.manager.models.utils import ExtendedAsyncSAEngine
from ai.backend.testutils.scenario_steps import Given, Says
from bai_scenario.components.domain import WAS_HERE, SomeoneOf
from bai_scenario.seeds.domain.domain import TestSeedDomain
from bai_scenario.seeds.rbac.role import TestSeedPermission, TestSeedRole
from bai_scenario.seeds.seeder import Laid, TestSeeder, TestSeedNest
from bai_scenario.seeds.user.fields import (
    TestSeedConfigFileOf,
    TestSeedConfigFileRevisionOf,
    TestSeedDefaultConfigFileOf,
)

CONFIG_PATH = ".vimrc"
CONFIG_PERMISSION = "644"
CONFIG_DATA = "set number\n"
UPDATED_PERMISSION = "600"
UPDATED_DATA = "set nonumber\n"
LATEST_DATA = "set relativenumber\n"
OTHER_PATH = ".bashrc"
OTHER_DATA = "export EDITOR=vim\n"


@dataclass(frozen=True)
class AUserAndTheirOwnConfig:
    """auto-generated file 의 주인과, 그 주인에게 권한을 받은 사람. 둘은 같은 사람이다.

    ``files`` 는 심은 순서대로고, ``revisions`` 는 ``files`` 의 파일마다 심은 revision 이다."""

    owner: UserData
    files: tuple[AutoGeneratedFileData, ...] = ()
    revisions: tuple[tuple[AutoGeneratedFileRevisionData, ...], ...] = ()


@dataclass(frozen=True)
class AConfigFileGrant(TestSeedNest[Laid[None]]):
    """사용자 자신을 스코프로 한 역할에 auto-generated file 권한을 담아 그 사용자에게 준다."""

    owner: Laid[UserData]
    permissions: Sequence[Permission]

    @override
    def kind(self) -> str:
        names = ", ".join(str(one.name) for one in self.permissions)
        return Says(
            f"자기 auto-generated file {names} 권한을 부여한 역할 배정",
            english=f"a role assignment granting the {names} permissions on their own auto-generated files",
        )

    @override
    def lay(self, seed: TestSeeder) -> Laid[None]:
        role = seed.creating_from(
            TestSeedRole(lambda one: UserID(one.id), name_hint="config-file-role"), self.owner
        )
        for permission in self.permissions:
            seed.adding(
                TestSeedPermission(
                    entity_type=AutoGeneratedFileEntityType(), permission=permission
                ),
                role,
            )
        return seed.granting(
            role, self.owner, role_id=lambda one: one.id, user_id=lambda one: UserID(one.id)
        )


@dataclass(frozen=True)
class AConfigFileToLay:
    """심을 auto-generated file 하나. 내용은 그 파일의 revision 1 이고, ``later`` 는 그 뒤에
    차례로 쓴 revision 의 내용이다."""

    path: str
    data: str
    is_default: bool
    later: tuple[str, ...] = ()


THE_DEFAULT_FILE = AConfigFileToLay(CONFIG_PATH, CONFIG_DATA, is_default=True)
A_FILE_NOT_DEFAULT = AConfigFileToLay(CONFIG_PATH, CONFIG_DATA, is_default=False)
ANOTHER_FILE_NOT_DEFAULT = AConfigFileToLay(OTHER_PATH, OTHER_DATA, is_default=False)
ANOTHER_DEFAULT_FILE = AConfigFileToLay(OTHER_PATH, OTHER_DATA, is_default=True)


@dataclass(frozen=True)
class SomeoneWithTheirOwnConfig(Given[Any, AUserAndTheirOwnConfig]):
    """도메인 하나와 사용자 하나. ``permissions``만큼 자기 auto-generated file 권한을 받고, ``files``를 갖는다.

    ``stranger_file``이면 같은 도메인의 다른 사용자가 default 로 지정된 파일 하나를 갖는다."""

    permissions: tuple[Permission, ...] = ()
    files: tuple[AConfigFileToLay, ...] = ()
    stranger_file: bool = False

    @override
    def describe(self) -> str:
        parts_ko = ["도메인 하나와 사용자 하나"]
        parts_en = ["one domain and one user"]
        for one in self.files:
            state_ko = "default 로 지정된" if one.is_default else "default 로 지정되지 않은"
            state_en = "set as default" if one.is_default else "not set as default"
            later_ko = "".join(
                f", revision {number} 의 내용 {data!r}"
                for number, data in enumerate(one.later, start=2)
            )
            later_en = "".join(
                f", revision {number} holding {data!r}"
                for number, data in enumerate(one.later, start=2)
            )
            parts_ko.append(
                f"사용자는 {state_ko} {one.path} auto-generated file 을 갖고 있습니다"
                f"(권한 {CONFIG_PERMISSION}, revision 1 의 내용 {one.data!r}{later_ko})"
            )
            parts_en.append(
                f"the user holds a {one.path} auto-generated file {state_en} "
                f"(permission {CONFIG_PERMISSION}, revision 1 holding {one.data!r}{later_en})"
            )
        if self.stranger_file:
            parts_ko.append(
                f"같은 도메인의 다른 사용자는 default 로 지정된 {CONFIG_PATH} auto-generated file 을 "
                "갖고 있습니다"
            )
            parts_en.append(
                f"another user of the domain holds a {CONFIG_PATH} auto-generated file set as "
                "default"
            )
        if self.permissions:
            names = ", ".join(str(p.name) for p in self.permissions)
            parts_ko.append(f"사용자는 자기 auto-generated file 에 대한 {names} 권한을 받았습니다")
            parts_en.append(
                f"the user holds the {names} permission on their own auto-generated files"
            )
        else:
            parts_ko.append("사용자는 아무 권한도 받지 않았습니다")
            parts_en.append("the user holds no permission")
        return Says(", ".join(parts_ko), english=", ".join(parts_en))

    @override
    async def lay(self, seeding: Any) -> AUserAndTheirOwnConfig:
        domain = await seeding.creating(TestSeedDomain(name_hint="home", description=WAS_HERE))
        owner = await seeding.within(SomeoneOf(domain))
        laid_files = [await self._lay_file(seeding, owner, one) for one in self.files]
        if self.stranger_file:
            stranger = await seeding.within(SomeoneOf(domain))
            await self._lay_file(seeding, stranger, THE_DEFAULT_FILE)
        if self.permissions:
            await seeding.within(AConfigFileGrant(owner, self.permissions))
        return AUserAndTheirOwnConfig(
            owner=seeding.made(owner),
            files=tuple(file for file, _ in laid_files),
            revisions=tuple(revisions for _, revisions in laid_files),
        )

    @staticmethod
    async def _lay_file(
        seeding: Any, owner: Laid[UserData], one: AConfigFileToLay
    ) -> tuple[AutoGeneratedFileData, tuple[AutoGeneratedFileRevisionData, ...]]:
        file = await seeding.creating_from(
            TestSeedConfigFileOf(lambda user: UserID(user.id), path=one.path),
            owner,
        )
        revisions: list[AutoGeneratedFileRevisionData] = []
        for data in (one.data, *one.later):
            revision = await seeding.adding(
                TestSeedConfigFileRevisionOf(
                    data=data, perm=CONFIG_PERMISSION, creator_id=UserID(seeding.made(owner).id)
                ),
                file,
            )
            revisions.append(seeding.made(revision))
        if one.is_default:
            file = await seeding.creating_from(TestSeedDefaultConfigFileOf(path=one.path), file)
        laid: AutoGeneratedFileData = seeding.made(file)
        return laid, tuple(revisions)


async def config_files_left(
    engine: ExtendedAsyncSAEngine,
) -> list[tuple[str, bool, list[tuple[int, str, str]]]]:
    """이 실행이 남긴 auto-generated file 행과, 파일마다 revision 번호와 권한과 내용."""
    async with engine.begin_readonly_session() as session:
        rows = await session.execute(
            sa.select(
                AutoGeneratedFileRow.id,
                AutoGeneratedFileRow.path,
                AutoGeneratedFileRow.is_default,
                AutoGeneratedFileRevisionRow.revision_number,
                AutoGeneratedFileRevisionRow.perm,
                AutoGeneratedFileRevisionRow.data,
            )
            .join(
                AutoGeneratedFileRevisionRow,
                AutoGeneratedFileRevisionRow.file_id == AutoGeneratedFileRow.id,
            )
            .order_by(
                AutoGeneratedFileRow.path,
                AutoGeneratedFileRow.is_default,
                AutoGeneratedFileRevisionRow.revision_number,
            )
        )
        files: dict[Any, tuple[str, bool, list[tuple[int, str, str]]]] = {}
        for row in rows:
            file = files.setdefault(row.id, (row.path, row.is_default, []))
            file[2].append((row.revision_number, row.perm, row.data))
        return list(files.values())
